[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$TaskDirectory,[Parameter(Mandatory=$true)][string]$ResearchJson)
$ErrorActionPreference='Stop'; Import-Module (Join-Path $PSScriptRoot 'PipelineProtocolV2.psm1') -Force
$value=Get-Content -Raw $ResearchJson|ConvertFrom-Json;if($value.sufficiency.status -ne 'sufficient'){throw 'research sufficiency must be sufficient'};foreach($b in 'rules_read','interfaces_checked','scope_limited','floors_justified','targets_justified','alternatives_considered'){if(-not [bool]$value.sufficiency.$b){throw "research sufficiency flag missing: $b"}};if(@($value.material_open).Count -gt 0){throw 'material research questions remain open'};if(@($value.sources).Count -eq 0){throw 'research requires sources'};$dir=Join-Path $TaskDirectory 'research-revisions';[IO.Directory]::CreateDirectory($dir)|Out-Null;$id='RESREV-{0:D4}' -f ((Get-ChildItem $dir -Filter '*.json' -ErrorAction SilentlyContinue).Count+1);$file=Join-Path $dir "$id.json";Write-PipelineImmutableJson $file $value|Out-Null;$hash=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant();Write-AtomicJson (Join-Path $TaskDirectory 'research-current.json') ([ordered]@{revision_id=$id;path=$file;sha256=$hash});[pscustomobject]@{path=$file;revision=$id}|ConvertTo-Json
